{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 따릉이(공공자전거) 이용 중 이용자 부주의로 부품이 망가진 경우 시가 수리비를 부담하거나 그냥 고쳐 주는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 조례상 공공자전거는 시가 관리하는 자전거로서 무상 또는 유상으로 시민 이용에 제공되는 자전거이다(제2조제5호). 이용자가 고의 또는 과실 등의 귀책사유로 공공자전거의 도난·분실·파손 등의 손실을 초래한 경우, 시장은 이용자에게 원상복구 또는 손해배상을 요구할 수 있다(제12조의2제6항). 따라서 이용자 부주의로 부품이 망가진 경우 공공자전거라는 이유만으로 시가 수리비를 부담하거나 그냥 고쳐 주는 것이 아니라, 시가 이용자에게 원상복구 또는 손해배상을 요구할 수 있다.",
          "b_ids": "자전거:제2조제5호, 자전거:제12조의2제6항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
